import re

# Chinese / English question and semicolon punctuation used to split
# multi-part questions into substantive clauses.
_CLAUSE_SPLIT_RE = re.compile(r"[?？;；!！。]+")
# Tokens: English words (length >= 2) or runs of CJK characters.
_TOKEN_RE = re.compile(r"[A-Za-z]{2,}|[\u4e00-\u9fff]+")
# Very common Chinese function characters that carry little meaning on their own.
_CJK_STOP_CHARS = set("的了和与及或是在有请我你他她它们这那哪个什么怎样如何为吗呢吧啊")


def _tokens(text):
    """Return a set of meaningful tokens for ``text``.

    English words are lowercased. CJK runs are expanded into overlapping
    bigrams (and the whole run when short) so that partial matches still work.
    """
    tokens = set()
    for match in _TOKEN_RE.findall(text or ""):
        if match.isascii():
            tokens.add(match.lower())
            continue
        run = "".join(ch for ch in match if ch not in _CJK_STOP_CHARS)
        if len(run) < 2:
            continue
        if len(run) == 2:
            tokens.add(run)
        else:
            for i in range(len(run) - 1):
                tokens.add(run[i:i + 2])
    return tokens


def _split_clauses(query):
    """Split a query into substantive clauses on question/semicolon punctuation."""
    clauses = []
    for part in _CLAUSE_SPLIT_RE.split(query or ""):
        part = part.strip()
        if not part:
            continue
        if _tokens(part):
            clauses.append(part)
    return clauses


def _score(terms, chunk):
    if not terms:
        return 0
    return len(terms & _tokens(chunk.get("text", "")))


def _chunk_key(chunk):
    if "id" in chunk:
        return ("id", chunk["id"])
    return ("obj", chunk.get("source"), chunk.get("page"), chunk.get("text"))


def search_context(chunks, query, top_k=2, neighbor_window=1, max_context=6):
    chunks = list(chunks or [])
    try:
        top_k = max(0, int(top_k))
    except (TypeError, ValueError):
        top_k = 0
    try:
        neighbor_window = max(0, int(neighbor_window))
    except (TypeError, ValueError):
        neighbor_window = 0
    try:
        max_context = max(0, int(max_context))
    except (TypeError, ValueError):
        max_context = 0

    if not chunks or max_context <= 0:
        return []

    clauses = _split_clauses(query)
    if not clauses:
        clauses = [query or ""]

    # Rank chunks once by overall relevance; used as a tie-breaker.
    overall_terms = _tokens(query or "")
    order = {_chunk_key(c): i for i, c in enumerate(chunks)}
    ranked = sorted(
        chunks,
        key=lambda c: (-_score(overall_terms, c), order[_chunk_key(c)]),
    )

    selected = []
    selected_keys = set()

    def add(chunk, reason):
        key = _chunk_key(chunk)
        if key in selected_keys:
            return False
        selected_keys.add(key)
        selected.append({**chunk, "retrieval_reason": reason})
        return True

    # Reserve at least one relevant semantic anchor per substantive clause.
    for clause in clauses:
        if len(selected) >= max_context:
            break
        terms = _tokens(clause)
        best = None
        best_score = 0
        for chunk in ranked:
            if _chunk_key(chunk) in selected_keys:
                continue
            score = _score(terms, chunk)
            if score > best_score:
                best, best_score = chunk, score
        if best is not None:
            add(best, "semantic")

    # Fill remaining semantic slots with the best overall matches.
    for chunk in ranked:
        if len(selected) >= max_context:
            break
        if _chunk_key(chunk) in selected_keys:
            continue
        if _score(overall_terms, chunk) <= 0:
            continue
        add(chunk, "semantic")

    # Add same-source neighboring pages around semantic anchors.
    if neighbor_window > 0 and len(selected) < max_context:
        by_source = {}
        for chunk in chunks:
            page = chunk.get("page")
            if page is None:
                continue
            by_source.setdefault(chunk.get("source"), []).append(chunk)

        anchors = list(selected)
        for anchor in anchors:
            if len(selected) >= max_context:
                break
            page = anchor.get("page")
            if page is None:
                continue
            try:
                page_num = int(page)
            except (TypeError, ValueError):
                continue
            siblings = by_source.get(anchor.get("source"), [])
            neighbors = []
            for chunk in siblings:
                try:
                    other = int(chunk.get("page"))
                except (TypeError, ValueError):
                    continue
                distance = abs(other - page_num)
                if 0 < distance <= neighbor_window:
                    neighbors.append((distance, order[_chunk_key(chunk)], chunk))
            neighbors.sort(key=lambda item: (item[0], item[1]))
            for _, _, chunk in neighbors:
                if len(selected) >= max_context:
                    break
                add(chunk, "neighbor")

    return selected[:max_context]
